-- V189: 6 объёмных лекций Академии Асгарда (по 1 на трек)
-- Пустые треки (finance, procurement, management, all) получают свой первый реальный урок.
-- Заполненные (pm, hr) получают month=14 как продолжение V147/V148.
-- Формат блоков совместим с office_academy.js Block Renderer.
BEGIN;

-- ════════════════════════════════════════════════════════════════════════════
-- FINANCE — Управленческий и бухгалтерский учёт: РСБУ, МСФО, упрощёнка
-- ════════════════════════════════════════════════════════════════════════════

WITH lesson AS (
  INSERT INTO office_academy_lessons
    (month_number, track, title, saga, cover_icon, cover_color,
     blocks, estimated_minutes, tags, is_mandatory, status, generated_by,
     published_at, release_date)
  VALUES (
    7, 'finance', 'Управленческий vs бухгалтерский учёт: что для чего',
    'Финансовый щит', '💰', '#1e2e18',
    $blocks$[
      {"type":"cover","icon":"💰","title":"Управленческий vs бухгалтерский учёт: что для чего","subtitle":"Почему одна и та же прибыль может быть 12 или 47 млн — в зависимости от того, кто считает"},
      {"type":"intro","text":"Многие в Асгарде уверены: «учёт — это бухгалтерия, мне не интересно». Это ошибка. Бухгалтерия — для государства. Управленческий учёт — для руководителя, чтобы решать. Один и тот же контракт может в бухучёте дать прибыль 12 млн, а в управленческом — убыток 5 млн. Кто прав? Оба. Но решения принимать по одному, а отчитываться — по другому. Эта лекция учит видеть разницу и не путать."},
      {"type":"text_block","title":"Бухгалтерский учёт — для государства","text":"Бухгалтерский учёт ведётся по правилам, которые устанавливает Минфин (РСБУ — Российские стандарты бухгалтерского учёта). Главная задача — правильно посчитать налоги: НДС, налог на прибыль, на имущество, на землю. Цикл — месяц/квартал/год. Жёстко регламентирован: каждая операция оформляется первичным документом (акт, накладная, счёт-фактура), записывается в журнал, попадает в баланс. Бухгалтерия ОТВЕЧАЕТ перед ФНС, поэтому всё «по букве» — даже если это медленно и неудобно. Ошибка в бухучёте — штраф или уголовная статья. Поэтому бухгалтер консервативен: лучше отразить позже, лучше не признать пока документов нет, лучше согласовать с аудитором."},
      {"type":"text_block","title":"Управленческий учёт — для руководителя","text":"Управленческий учёт ведётся по правилам, которые устанавливает САМ руководитель компании. Главная задача — дать менеджменту цифры для принятия решений: эта работа выгодна или нет? этот заказчик прибыльный или убыточный? стоит ли брать новый объект? Цикл — день/неделя/месяц, гораздо чаще бухучёта. Не регламентирован — каждая компания делает по-своему. ОТЧИТЫВАЕТСЯ перед собственником и директором. Поэтому управленческий аналитик гибок: лучше быстро и приблизительно, чем правильно через 2 месяца. Может включать неучтённые в бухучёте затраты (амортизация репутации, упущенная выгода), может разносить накладные по проектам по-своему."},
      {"type":"icon_grid","title":"Главные отличия — таблица для запоминания","items":[
        {"icon":"📊","label":"Цель: налоги vs решения","desc":"Бух — что заплатить ФНС. Упр — куда вкладывать"},
        {"icon":"⚖️","label":"Правила: РСБУ vs внутренние","desc":"Бух — по закону. Упр — как удобно компании"},
        {"icon":"⏱️","label":"Цикл: квартал vs неделя","desc":"Бух — медленнее. Упр — оперативнее"},
        {"icon":"👁️","label":"Кому отчёт: ФНС vs директор","desc":"Бух — внешний. Упр — внутренний"},
        {"icon":"📜","label":"Документы: жёстко vs гибко","desc":"Бух — каждая копейка с актом. Упр — допустимы оценки"},
        {"icon":"💼","label":"Ответственность: ст.199 УК vs увольнение","desc":"Бух — уголовная. Упр — карьерная"}
      ]},
      {"type":"text_block","title":"Зачем два учёта — и где они расходятся","text":"Простой пример. Асгард в марте подписал акт по работе на 50 млн руб. — заказчик принял. Бухгалтерия закрывает выручку 50 млн в марте. Управленческий учёт уже в феврале закрыл «фактический объём работ» 50 млн, потому что работы реально были сделаны в феврале. Февральская прибыль в управленческом — 8 млн. Мартовская в бухгалтерском — 8 млн. Сумма одна, но месяц разный. Если директор смотрит только бухучёт, он подумает: «февраль слабый, март сильный». На самом деле наоборот. Решение по премиям, штрафам, найму людей надо принимать по управленческому учёту, потому что он отражает реальность."},
      {"type":"warning","level":"warning","text":"Самая частая ошибка — принимать решения по бухгалтерским цифрам. Бухгалтерия отражает события по факту документов, а не по факту работы. Поэтому она всегда «опаздывает» на 1-2 месяца и сильно дрейфит при больших контрактах. Управленческий учёт быстрее и точнее для решений, хотя «менее правильный» с точки зрения закона."},
      {"type":"text_block","title":"РСБУ, МСФО, US GAAP — три мира","text":"РСБУ — Российские стандарты бухучёта (наследие советского учёта, налоговая ориентация). МСФО — Международные стандарты финансовой отчётности (общеевропейские/мировые, ориентированы на инвестора). US GAAP — стандарты США. Главное отличие РСБУ от МСФО — приоритеты. РСБУ ставит во главу «соответствие первичным документам», МСФО ставит «экономическое содержание операции». Пример: купили оборудование в лизинг за 100 млн. РСБУ скажет — на балансе 0 (не наш актив, лизингодателя). МСФО скажет — на балансе 100 млн (мы фактически им владеем и используем). Поэтому отчётность одной компании по РСБУ и МСФО может радикально различаться по активам и прибыли."},
      {"type":"icon_grid","title":"Когда какой стандарт нужен","items":[
        {"icon":"🇷🇺","label":"РСБУ — обязательный","desc":"Любая компания на ОСН в РФ. Для ФНС, отчётности"},
        {"icon":"🌍","label":"МСФО — для крупных","desc":"Публичные компании, выход на биржу, иностранные инвесторы"},
        {"icon":"🇺🇸","label":"US GAAP — для США","desc":"Только если работаете с американским рынком капитала"},
        {"icon":"📉","label":"Управленческий — внутренний","desc":"Свои правила, своя структура, ничьим стандартам не подчиняется"}
      ]},
      {"type":"text_block","title":"Упрощёнка (УСН) — кому подходит","text":"Упрощённая система налогообложения (УСН) — это сокращённый формат для малого бизнеса. Объём выручки до 200 млн руб/год, штат до 130 человек, отсутствие филиалов. Две ставки на выбор: 6% от выручки (УСН-доходы) или 15% от прибыли (УСН-доходы минус расходы). Плюсы: меньше бумаги, нет НДС (для конечного покупателя дешевле), один налог вместо трёх. Минусы: нельзя работать с заказчиком на ОСН без НДС-проблем, ограничения по виду деятельности, потеря режима при превышении лимита. Асгард работает на ОСН, потому что заказчики (нефтегаз) требуют НДС в счетах. Но если есть дочерняя компания на УСН — она может быть полезна для отдельных проектов."},
      {"type":"steps","title":"Алгоритм понимания финансового отчёта","items":[
        "Спросить ОТКУДА цифры — из бухгалтерии или из управленческого учёта",
        "Если бухгалтерский — смотреть отчётный период: за прошлый квартал, не текущий",
        "Если управленческий — спросить методику расчёта: как делят накладные, по чему амортизация",
        "Проверить выручку по периоду закрытия — у бух по акту, у упр по факту работ",
        "Найти расхождения с предыдущим периодом — есть ли разовые статьи (премии, штрафы, продажа активов)",
        "Сделать вывод по двум числам: маржинальность (валовая) и чистая прибыль/выручка"
      ]},
      {"type":"fact_card","icon":"💡","text":"2022 год, строительный холдинг Урала. Директор уволил начальника проекта за «убыточный квартал» — бухгалтерия показала минус 18 млн. Через 3 месяца проверка управленческого учёта показала: квартал был с прибылью 22 млн, просто акт по крупной работе закрыли в следующем квартале. Уволенный начальник проекта подал в суд и выиграл компенсацию 4 млн руб. Директор теперь требует ОБА отчёта на каждом совещании. Цена незнания разницы — 22 млн упущенной прибыли + 4 млн компенсации."},
      {"type":"text_block","title":"Cash и Profit — два разных мира","text":"Прибыль (Profit) — это разница между выручкой и расходами. Деньги (Cash) — это реально пришедшие на счёт и реально ушедшие со счёта. Это совершенно разные вещи! Компания может быть прибыльной по отчётам и при этом сидеть без денег: акт подписан, выручка отражена, но заказчик пока не заплатил (дебиторка 100 млн). Или наоборот: убыточный отчёт, но деньги есть (получили аванс 50 млн, выручку ещё не заработали — это кредиторка). Решения по cash принимаются совсем не так, как по прибыли. Cash-flow прогноз — отдельный документ, который ведёт финансовый директор каждую неделю."},
      {"type":"warning","level":"danger","text":"Прибыльная компания может обанкротиться при отличных финансовых отчётах. Это явление называется «кассовый разрыв». Бухгалтерия сообщает прибыль 30 млн, а на счёте 2 млн — потому что заказчики не заплатили вовремя. Зарплату платить нечем. Кредит не дают (банк смотрит на cash, а не на прибыль). Эта ловушка убила больше компаний, чем убыточные проекты."},
      {"type":"fact_card","icon":"⚠️","text":"Apple в 2000 году была близка к банкротству при показанной прибыли. Стив Джобс вернулся, провёл аудит cash-flow, оказалось: компания прибыльная, но дебиторская задолженность съела всю ликвидность. Джобс заставил CFO еженедельно докладывать о cash-flow на совете директоров. С тех пор Apple — одна из самых cash-богатых компаний в мире (на 2026 ≈ 80 млрд $ в кэше). Урок Apple: прибыль — это иллюзия, cash — это реальность."}
    ]$blocks$::jsonb,
    20, ARRAY['финансы','рсбу','мсфо','учёт'], false, 'published', 'manual',
    NOW(), CURRENT_DATE
  )
  RETURNING id
)
INSERT INTO office_academy_quiz_questions (lesson_id, sort_order, question_type, question_text, options, correct_explanation)
SELECT lesson.id, q.so, q.qt, q.qtext, q.opts::jsonb, q.expl FROM lesson, (VALUES
  (1, 'choice', 'Главная цель бухгалтерского учёта в России:',
   '[{"id":1,"text":"Принятие управленческих решений","is_correct":false},{"id":2,"text":"Расчёт налогов и отчётность для ФНС","is_correct":true},{"id":3,"text":"Прогнозирование cash-flow","is_correct":false},{"id":4,"text":"Анализ прибыльности проектов","is_correct":false}]',
   'Бухгалтерский учёт по РСБУ направлен на правильный расчёт налогов и формирование отчётности для ФНС. Это его регуляторная функция. Для решений и анализа используется управленческий учёт — он гибче и оперативнее.'),
  (2, 'choice', 'Чем РСБУ отличается от МСФО в принципе?',
   '[{"id":1,"text":"РСБУ — на русском, МСФО — на английском","is_correct":false},{"id":2,"text":"РСБУ ставит соответствие документам, МСФО — экономическое содержание","is_correct":true},{"id":3,"text":"РСБУ для крупных, МСФО для малых","is_correct":false},{"id":4,"text":"Они одинаковы","is_correct":false}]',
   'Главное концептуальное отличие: РСБУ ставит во главу «соответствие первичным документам» (формальный подход), а МСФО — «экономическое содержание операции» (что фактически произошло). Поэтому лизинговое оборудование в РСБУ может не отражаться на балансе, а в МСФО — отражаться.'),
  (3, 'truefalse', 'Прибыльная компания не может обанкротиться.',
   '[{"id":1,"text":"Верно","is_correct":false},{"id":2,"text":"Неверно","is_correct":true}]',
   'Прибыльная компания может обанкротиться от кассового разрыва: прибыль есть на бумаге (по актам), но дебиторская задолженность съела всю ликвидность, на счёте нет денег платить зарплату и поставщикам. Cash и Profit — разные вещи.'),
  (4, 'scenario', 'Директор требует немедленного отчёта о результатах проекта за июнь. Бухгалтерия говорит «закроем 25 июля». Что делать?',
   '[{"id":1,"text":"Ждать бухгалтерию — это правильные цифры","is_correct":false},{"id":2,"text":"Получить управленческие данные сейчас, бухгалтерские — позже для сравнения и налогов","is_correct":true},{"id":3,"text":"Сказать директору, что цифр нет","is_correct":false},{"id":4,"text":"Дать прогноз на глаз","is_correct":false}]',
   'Управленческий учёт быстрее и подходит для оперативных решений. Бухгалтерский — для налогов и официальной отчётности, он всегда отстаёт на 1-2 месяца. Профессиональный руководитель использует оба, но решения принимает по управленческому.'),
  (5, 'choice', 'Лимит выручки для применения УСН в 2026 году:',
   '[{"id":1,"text":"60 млн","is_correct":false},{"id":2,"text":"100 млн","is_correct":false},{"id":3,"text":"200 млн","is_correct":true},{"id":4,"text":"500 млн","is_correct":false}]',
   'Лимит для УСН — 200 млн руб/год по выручке. При превышении лимита компания переходит на ОСН. Также есть ограничение по штату (130 человек) и отсутствию филиалов.'),
  (6, 'choice', 'Почему Асгард работает на ОСН, а не на УСН?',
   '[{"id":1,"text":"ОСН проще","is_correct":false},{"id":2,"text":"Заказчики (нефтегаз) требуют НДС в счетах","is_correct":true},{"id":3,"text":"УСН запрещён для строительства","is_correct":false},{"id":4,"text":"ОСН даёт льготы","is_correct":false}]',
   'Крупные заказчики на ОСН не могут принять к вычету НДС от поставщика на УСН (его там нет). Поэтому для контрактов с ОСН-заказчиками поставщик тоже должен быть на ОСН. УСН подходит для работы с физлицами и малым бизнесом.'),
  (7, 'truefalse', 'Управленческий учёт регулируется законом так же строго, как бухгалтерский.',
   '[{"id":1,"text":"Верно","is_correct":false},{"id":2,"text":"Неверно","is_correct":true}]',
   'Управленческий учёт регулируется только внутренними правилами компании. Закона про него нет. За ошибки в управленческом учёте не штрафуют ФНС, отвечают только перед собственником/директором (карьерная ответственность).'),
  (8, 'scenario', 'Бухгалтерия показала по проекту прибыль 18 млн, управленческий — убыток 4 млн. Кто прав?',
   '[{"id":1,"text":"Бухгалтерия — она по документам","is_correct":false},{"id":2,"text":"Управленческий — он по сути","is_correct":false},{"id":3,"text":"Оба правы, но считают разное — нужно понять методики обоих и причины расхождения","is_correct":true},{"id":4,"text":"Никто не прав, ошибки","is_correct":false}]',
   'Оба расчёта могут быть корректными в своей системе. Расхождение в 22 млн стоит изучить: бухгалтерия не учла дополнительные затраты (упущенная выгода, амортизация репутации), управленческий — закрыл выручку по факту работ, а бух — по акту. Разобраться в причинах, а не выбирать.'),
  (9, 'choice', 'Какой ставкой УСН чаще пользуются строительные компании?',
   '[{"id":1,"text":"6% от выручки","is_correct":false},{"id":2,"text":"15% от прибыли (доходы минус расходы)","is_correct":true},{"id":3,"text":"3% от себестоимости","is_correct":false},{"id":4,"text":"20% от чистой прибыли","is_correct":false}]',
   'Стройка — это много материалов и подрядных работ (расходы большие). УСН-15% от прибыли выгоднее, чем 6% от выручки. УСН-6% подходит для услуг и торговли, где расходов мало.'),
  (10, 'truefalse', 'Дебиторская задолженность 100 млн в отчёте — это плохо.',
   '[{"id":1,"text":"Верно","is_correct":false},{"id":2,"text":"Неверно — это зависит от контекста","is_correct":true}]',
   'Дебиторка 100 млн — нейтральный показатель. Хорошо: продали много, скоро деньги придут. Плохо: если просрочка большая или заказчики ненадёжные. Анализируется по срокам (старение долга) и качеству заказчиков.')
) AS q(so, qt, qtext, opts, expl);


-- ════════════════════════════════════════════════════════════════════════════
-- PROCUREMENT — 44-ФЗ vs 223-ФЗ: ключевые отличия, риски, штрафы
-- ════════════════════════════════════════════════════════════════════════════

WITH lesson AS (
  INSERT INTO office_academy_lessons
    (month_number, track, title, saga, cover_icon, cover_color,
     blocks, estimated_minutes, tags, is_mandatory, status, generated_by,
     published_at, release_date)
  VALUES (
    7, 'procurement', '44-ФЗ и 223-ФЗ: отличия, риски, штрафы',
    'Арсенал поставок', '📦', '#2e1e18',
    $blocks$[
      {"type":"cover","icon":"📦","title":"44-ФЗ и 223-ФЗ: отличия, риски, штрафы","subtitle":"Два закона, которые определяют 80% контрактов с госзаказчиками"},
      {"type":"intro","text":"Если компания работает с государственными заказчиками — а нефтегаз во многом государственный (Газпром, Роснефть, дочки) — то 44-ФЗ и 223-ФЗ касаются вас лично. Ошибка в подаче заявки на тендер по 44-ФЗ — отклонение и штраф до 100 тыс. Ошибка в исполнении контракта по 44-ФЗ — реестр недобросовестных поставщиков на 2 года (фактический запрет на госконтракты). Знание этих законов — это не «бухгалтерское дело», это вопрос выживания компании. Лекция — практическая, без юридического тумана."},
      {"type":"text_block","title":"44-ФЗ vs 223-ФЗ — кто где","text":"44-ФЗ регулирует закупки чисто государственных и муниципальных заказчиков: министерства, школы, больницы, силовые ведомства. Строжайший контроль: вся документация открыто публикуется, торги в электронной форме, чёткие сроки, ограниченные основания для отказа. 223-ФЗ — для госкомпаний и компаний с государственной долей (Газпром, Роснефть, РЖД, Росатом). Каждая такая компания пишет своё «Положение о закупке» в рамках 223-ФЗ — поэтому процедуры сильно различаются. Газпром и Роснефть имеют свои электронные торговые площадки (Газпромбанк-ЭТП, ТЭК-Торг) с правилами, иногда строже 44-ФЗ. Но контроль ФАС над 223-ФЗ слабее — больше пространства для манёвра."},
      {"type":"icon_grid","title":"44-ФЗ vs 223-ФЗ — таблица различий","items":[
        {"icon":"🏛️","label":"Заказчик","desc":"44-ФЗ — государственные органы. 223-ФЗ — госкорпорации и компании с госдолей >50%"},
        {"icon":"📜","label":"Процедуры","desc":"44-ФЗ — единые для всех (7 типов). 223-ФЗ — каждый заказчик пишет своё положение"},
        {"icon":"🌐","label":"Площадки","desc":"44-ФЗ — 8 аккредитованных ЭТП. 223-ФЗ — своя у каждого крупного заказчика"},
        {"icon":"⏰","label":"Сроки подачи","desc":"44-ФЗ — жёстко по закону. 223-ФЗ — по положению (часто короче)"},
        {"icon":"⚖️","label":"Контроль","desc":"44-ФЗ — ФАС жёсткий. 223-ФЗ — ФАС мягче, но Минэнерго и аудит"},
        {"icon":"🚫","label":"Реестр недобросовестных","desc":"Единый РНП на 2 года. Срыв контракта = запрет на оба закона"}
      ]},
      {"type":"text_block","title":"Реестр недобросовестных поставщиков (РНП) — главная угроза","text":"РНП — это публичный список компаний и их учредителей, которые сорвали госконтракт. Внесение происходит автоматически: заказчик подаёт жалобу в ФАС, ФАС включает в РНП на 2 года. На 2 года компания НЕ МОЖЕТ участвовать в торгах по 44-ФЗ и по 223-ФЗ (большинство положений запрещают РНП). Для отдельных регионов и отраслей запрет может быть пожизненным. Учредители РНП-компании тоже под запретом — нельзя зарегистрировать новое ООО для обхода. Основания для попадания: расторжение контракта по вине поставщика, существенное нарушение сроков, поставка не того товара, банкротство во время исполнения. Один контракт в РНП — это конец госнаправления для компании."},
      {"type":"warning","level":"danger","text":"Самая опасная ошибка — взять контракт «с запасом по срокам» и сорвать. Лучше отказаться на этапе участия (потеря обеспечения заявки 0.5-5% от НМЦК), чем сорвать на этапе исполнения (РНП + штрафы + потеря репутации). Анализ выполнимости контракта — главная задача отдела закупок ДО подачи заявки."},
      {"type":"text_block","title":"Антидемпинг — почему нельзя сильно снижать цену","text":"44-ФЗ имеет защиту от демпинга. Если участник снижает цену больше чем на 25% от НМЦК (начальной максимальной цены контракта), включаются «антидемпинговые меры». В зависимости от размера контракта: до 15 млн — обоснование снижения и/или увеличенное обеспечение (от 1.5 раз), от 15 млн — обеспечение увеличено в 1.5 раза + положительная деловая репутация (исполненные контракты в реестре). Цель закона — не пустить дешёвых исполнителей-однодневок. На практике это значит: снижение более 25% — это серьёзный риск, а более 40% — почти всегда финансовый минус для исполнителя."},
      {"type":"icon_grid","title":"Типы процедур по 44-ФЗ — что используется чаще","items":[
        {"icon":"📊","label":"Электронный аукцион","desc":"50% всех закупок. Победитель — кто дал минимальную цену"},
        {"icon":"📝","label":"Электронный конкурс","desc":"Оценка по нескольким критериям — цена, опыт, сроки"},
        {"icon":"💡","label":"Запрос котировок","desc":"До 3 млн, быстрая процедура, минимум документов"},
        {"icon":"🏗️","label":"Закупка у единственного поставщика","desc":"Без торгов — для уникальных или малых закупок"},
        {"icon":"🔒","label":"Закрытый аукцион","desc":"Гостайна, только аккредитованные участники"},
        {"icon":"🌐","label":"Запрос предложений","desc":"Для специфики, когда нужны проекты и наработки"}
      ]},
      {"type":"text_block","title":"Обеспечение заявки и контракта — что это и сколько","text":"При участии в торгах по 44-ФЗ участник вносит обеспечение заявки: 0.5-5% от НМЦК. Если выиграл и подписал контракт — деньги возвращаются. Если выиграл и отказался от подписания — обеспечение «сгорает» + автоматический РНП. Обеспечение контракта (исполнения обязательств) — 5-30% от цены контракта, вносится после подписания, возвращается после исполнения. Можно деньгами или банковской гарантией. Банковская гарантия удобнее (не замораживаются деньги), но стоит 2-5% годовых от суммы. Для крупных контрактов 100+ млн обеспечение становится серьёзным финансовым решением — может потребоваться кредитная линия."},
      {"type":"steps","title":"Алгоритм участия в торгах по 44-ФЗ","items":[
        "Найти закупку в ЕИС (Единая информационная система) zakupki.gov.ru, изучить документацию",
        "Проверить требования к участнику: ОКВЭДы, лицензии, опыт, отсутствие в РНП",
        "Оценить выполнимость по срокам, ресурсам, кадрам. Запросить разъяснения у заказчика, если есть неясности",
        "Подготовить заявку: смета, опыт, банковские реквизиты для обеспечения, подписать ЭЦП",
        "Внести обеспечение заявки на спецсчёт через ЭТП (0.5-5% от НМЦК)",
        "В день аукциона — ставки в режиме онлайн, шаг 0.5-5% от НМЦК",
        "Если победил — за 5-10 дней подписать контракт через ЭЦП и внести обеспечение исполнения (5-30%)",
        "Исполнять контракт строго по календарному плану, отчитываться в ЕИС"
      ]},
      {"type":"fact_card","icon":"💀","text":"2021 год, региональная стройкомпания взяла подряд на ремонт школы по 44-ФЗ за 12 млн (НМЦК 18 млн, снижение 33%). Антидемпинг сработал, увеличенное обеспечение внесли. Через 3 месяца стало ясно: материалы подорожали, рабочих не хватает, в смете не учли вывоз грунта. Компания просрочила сдачу на 2 месяца, заказчик расторг контракт. ФАС внесла в РНП. Компания и её директор не могут участвовать в госзакупках до 2023 года, и второй учредитель — тоже. Потеря бизнеса: годовая выручка падала на 80% (вся была от госзаказчиков). Урок: 33% снижение — это уже зона риска, надо считать трижды."},
      {"type":"text_block","title":"Штрафы за нарушения — реальные суммы","text":"Заказчик в случае нарушений поставщиком начисляет пени (1/300 ставки рефинансирования ЦБ за каждый день просрочки от цены контракта) и штрафы (10-1000 тыс руб за нарушения, не связанные с просрочкой — некачественный товар, неверная документация, нарушение порядка). Эти штрафы НЕ обсуждаемые — они в каждом госконтракте по типовой форме. Кроме того, ФАС может оштрафовать компанию за антимонопольные нарушения (картельный сговор на торгах — миллионы), за уклонение от заключения контракта (до 100 тыс), за подачу недостоверной информации (до 500 тыс). Директор лично может быть привлечён по КоАП — штрафы 30-50 тыс руб + дисквалификация (запрет занимать руководящие должности) на 3-6 лет."},
      {"type":"warning","level":"warning","text":"Картельный сговор на торгах — самое опасное нарушение. Это когда 2-3 «конкурирующие» компании договариваются не торговаться друг с другом, по очереди выигрывая контракты. ФАС системно ловит такие схемы (анализ поведения, IP-адреса, email-переписка). Штрафы — 3-15% от выручки виновной компании, плюс уголовная ст. 178 УК (до 7 лет). Никогда не обсуждайте торги с конкурентами, даже в шутку. Лучшая защита — никаких контактов с конкурентами в период торгов."},
      {"type":"fact_card","icon":"🛡️","text":"Лучшая практика 2024 года — компания «Уралспецстрой». Из 47 контрактов по 44-ФЗ за год — 0 жалоб в ФАС, 0 в РНП. Секрет: «У нас отдел закупок имеет право вето на любую заявку. Если они говорят «нет, не потянем» — мы не подаём, даже если коммерческий хочет. Лучше отказаться на старте, чем сорвать. За год отказались от 12 контрактов на 280 млн НМЦК — но взяли 35 на 470 млн и все исполнили». Это и есть профессионализм отдела закупок."}
    ]$blocks$::jsonb,
    20, ARRAY['закупки','44-фз','223-фз','тендер'], false, 'published', 'manual',
    NOW(), CURRENT_DATE
  )
  RETURNING id
)
INSERT INTO office_academy_quiz_questions (lesson_id, sort_order, question_type, question_text, options, correct_explanation)
SELECT lesson.id, q.so, q.qt, q.qtext, q.opts::jsonb, q.expl FROM lesson, (VALUES
  (1, 'choice', 'Кто работает по 44-ФЗ?',
   '[{"id":1,"text":"Только Газпром","is_correct":false},{"id":2,"text":"Государственные органы и муниципалитеты","is_correct":true},{"id":3,"text":"Любые частные компании","is_correct":false},{"id":4,"text":"Только малый бизнес","is_correct":false}]',
   '44-ФЗ регулирует закупки чисто государственных и муниципальных заказчиков: министерства, школы, больницы, силовые ведомства. Госкорпорации (Газпром, Роснефть) — это 223-ФЗ.'),
  (2, 'choice', 'На сколько лет вносят в реестр недобросовестных поставщиков?',
   '[{"id":1,"text":"6 месяцев","is_correct":false},{"id":2,"text":"1 год","is_correct":false},{"id":3,"text":"2 года","is_correct":true},{"id":4,"text":"Пожизненно","is_correct":false}]',
   'РНП — стандартно 2 года. На этот срок компания не может участвовать в торгах ни по 44-ФЗ, ни по большинству положений 223-ФЗ. Учредители тоже под запретом — нельзя зарегистрировать новую компанию для обхода.'),
  (3, 'truefalse', 'Если победил в торгах и отказался подписать контракт — попадаешь в РНП.',
   '[{"id":1,"text":"Верно","is_correct":true},{"id":2,"text":"Неверно","is_correct":false}]',
   'Уклонение от подписания контракта после победы = автоматический РНП + обеспечение заявки сгорает. Это одна из самых частых причин попадания в реестр.'),
  (4, 'choice', 'При каком снижении цены от НМЦК включается антидемпинг?',
   '[{"id":1,"text":"10%","is_correct":false},{"id":2,"text":"15%","is_correct":false},{"id":3,"text":"25%","is_correct":true},{"id":4,"text":"50%","is_correct":false}]',
   'Антидемпинг — при снижении более 25% от НМЦК. Меры: для контрактов до 15 млн — обоснование снижения и увеличенное обеспечение, выше 15 млн — обеспечение 1.5× + положительная деловая репутация.'),
  (5, 'scenario', 'Вы выиграли контракт со снижением 35% по 44-ФЗ. Через 2 месяца поняли, что не успеете в срок. Что делать?',
   '[{"id":1,"text":"Молчать и тянуть до последнего","is_correct":false},{"id":2,"text":"Открыто согласовать с заказчиком: дополнительное соглашение, обоснование причин, новый срок","is_correct":true},{"id":3,"text":"Не подписывать ничего и сорвать срок","is_correct":false},{"id":4,"text":"Передать контракт другой компании","is_correct":false}]',
   'В 44-ФЗ есть законная процедура — допсоглашение с обоснованием (форс-мажор, изменение проекта). Заказчик может или не может пойти навстречу, но честный разговор сохраняет шансы. Срыв без обсуждения = РНП. Передача контракта третьему лицу запрещена (есть исключения, но редко).'),
  (6, 'choice', 'Главная электронная торговая площадка для торгов Газпрома:',
   '[{"id":1,"text":"zakupki.gov.ru","is_correct":false},{"id":2,"text":"ЭТП Газпромбанка / ТЭК-Торг","is_correct":true},{"id":3,"text":"Сбербанк-АСТ","is_correct":false},{"id":4,"text":"РТС-Тендер","is_correct":false}]',
   'Газпром использует свои ЭТП — Газпромбанк-ЭТП, ТЭК-Торг. Это 223-ФЗ. Площадки 44-ФЗ (zakupki.gov.ru, Сбербанк-АСТ, РТС-Тендер) для государственных органов, не для госкорпораций.'),
  (7, 'truefalse', 'Картельный сговор на торгах — это «деловая практика», за неё не наказывают.',
   '[{"id":1,"text":"Верно","is_correct":false},{"id":2,"text":"Неверно — штрафы 3-15% выручки + уголовная ст. 178 УК","is_correct":true}]',
   'Картельный сговор — это уголовное преступление (ст. 178 УК, до 7 лет лишения свободы) и крупные штрафы ФАС (3-15% от выручки компании). ФАС системно ловит сговоры через анализ поведения, IP, email-переписки. Лучшая защита — никаких контактов с конкурентами в период торгов.'),
  (8, 'scenario', 'Конкурент звонит и предлагает «по-братски не пересекаться» на двух торгах. Что делать?',
   '[{"id":1,"text":"Согласиться — все так делают","is_correct":false},{"id":2,"text":"Отказаться, в идеале — записать разговор и сообщить руководству для самозащиты","is_correct":true},{"id":3,"text":"Сделать вид, что согласен, но торговаться","is_correct":false},{"id":4,"text":"Согласиться, но потом не выполнять","is_correct":false}]',
   'Любое подобное предложение — это попытка вовлечь вас в картель. Юридически опасно для вас и вашей компании. Если оно «разоблачится» ФАС, обе стороны попадут под уголовную ст. 178. Лучшая практика — отказ + фиксация разговора + сообщение руководству. Это защитит вас, если конкурент попытается переложить ответственность.'),
  (9, 'choice', 'Сколько составляет обеспечение исполнения контракта по 44-ФЗ?',
   '[{"id":1,"text":"0.5-5% от НМЦК","is_correct":false},{"id":2,"text":"5-30% от цены контракта","is_correct":true},{"id":3,"text":"50% от цены","is_correct":false},{"id":4,"text":"Не требуется","is_correct":false}]',
   '5-30% от цены контракта — обеспечение исполнения, вносится после подписания. Можно деньгами или банковской гарантией. Обеспечение заявки (0.5-5% от НМЦК) — это другая сумма, вносится до участия в торгах.'),
  (10, 'truefalse', 'Управление закупок имеет право заблокировать заявку, даже если коммерческий директор её хочет.',
   '[{"id":1,"text":"Верно — это профессиональная защита от РНП","is_correct":true},{"id":2,"text":"Неверно — приказ начальства всегда важнее","is_correct":false}]',
   'Профессиональный отдел закупок ОБЯЗАН блокировать заявки с высоким риском срыва — это защита всей компании от РНП. Лучшие практики (как «Уралспецстрой») дают отделу закупок право вето. Лучше отказаться от 280 млн контрактов, чем сорвать один и потерять весь госнаправление.')
) AS q(so, qt, qtext, opts, expl);


-- ════════════════════════════════════════════════════════════════════════════
-- MANAGEMENT — KPI и OKR: чем отличаются, когда что использовать
-- ════════════════════════════════════════════════════════════════════════════

WITH lesson AS (
  INSERT INTO office_academy_lessons
    (month_number, track, title, saga, cover_icon, cover_color,
     blocks, estimated_minutes, tags, is_mandatory, status, generated_by,
     published_at, release_date)
  VALUES (
    7, 'management', 'KPI и OKR: чем отличаются, когда что',
    'Путь лидера', '🎯', '#1a1830',
    $blocks$[
      {"type":"cover","icon":"🎯","title":"KPI и OKR: чем отличаются, когда что","subtitle":"Почему модный OKR убил уже сотни отделов, и где он реально работает"},
      {"type":"intro","text":"Каждые 3-5 лет в России появляется новая модная методология управления. Сначала это был BSC, потом Lean Six Sigma, потом Scrum, теперь OKR. Половина компаний внедряет, не понимая зачем. Через полгода — отказ, разочарование, новая методология. Эта лекция — про разницу между KPI и OKR на пальцах, без бизнес-литературы. Цель: понять, где какой инструмент работает, а где — вредит."},
      {"type":"text_block","title":"KPI — что это и для чего","text":"KPI (Key Performance Indicator) — ключевой показатель эффективности. Это конкретная цифра, которую сотрудник должен достичь за период (месяц, квартал, год). Примеры: «увеличить выручку отдела на 15%», «снизить просрочку дебиторки до 10%», «довести конверсию заявок до 18%». KPI работает там, где: задача повторяемая, результат измерим в цифрах, есть исторические данные для сравнения. Главная особенность — KPI обычно привязан к зарплате/премии. Не выполнил — нет премии. Перевыполнил — больше премия. Это создаёт давление на достижение цифры, но и фокусирует."},
      {"type":"text_block","title":"OKR — что это и для чего","text":"OKR (Objectives and Key Results) — Цели и Ключевые Результаты. Это пара из двух элементов: Цель — короткое мотивационное описание («Стать лидером рынка строительства Сибири»), Ключевые результаты — 3-5 измеримых критериев успеха («доля рынка 15%», «50 контрактов в год», «NPS 75%»). OKR ставится на квартал или год, обновляется регулярно. Главные отличия от KPI: 1) Амбициозность — OKR должен быть «растягивающим», достижение 70% — это успех, не провал. 2) НЕ привязан к зарплате. Привязка убивает амбициозность — люди начинают ставить заведомо лёгкие цели. 3) Прозрачность — все OKR публичны в компании, видны всем."},
      {"type":"icon_grid","title":"KPI vs OKR — основные отличия","items":[
        {"icon":"🎯","label":"Цель: достижение vs амбиция","desc":"KPI — выполнить 100%. OKR — попробовать 100%, достичь 70%"},
        {"icon":"💰","label":"Привязка к зарплате","desc":"KPI — да, премия зависит. OKR — нет, иначе не работает"},
        {"icon":"⏰","label":"Период","desc":"KPI — год/квартал. OKR — обычно квартал, проверка еженедельно"},
        {"icon":"🔒","label":"Прозрачность","desc":"KPI — личный/отдельский. OKR — публичный для всей компании"},
        {"icon":"🔄","label":"Гибкость","desc":"KPI — стабильный весь период. OKR — можно скорректировать в середине"},
        {"icon":"🏃","label":"Тип задач","desc":"KPI — повторяемые рутинные. OKR — новые амбициозные"}
      ]},
      {"type":"text_block","title":"Где какой работает — практика","text":"Отдел продаж со стабильным потоком клиентов: KPI работает идеально. «Делай больше продаж — получай больше премии». OKR здесь будет перебором. Команда запуска нового продукта: OKR работает идеально. KPI на «запуск с 10 000 пользователей в первый месяц» — это либо все врут о результате, либо демотивация. Нужна амбициозная цель и право на ошибку. Стройка с фиксированным графиком: KPI («сдать в срок, в смете, без претензий по качеству»). Стартап-направление: OKR. В большинстве компаний нужны ОБА инструмента: KPI для базовых процессов, OKR для новых направлений и стратегических инициатив."},
      {"type":"warning","level":"danger","text":"Главная ошибка — привязка OKR к зарплате. Если 70% достижение даёт 70% премии, люди начнут ставить заведомо слабые цели (чтобы достичь 100%) — и OKR превратится в KPI с другим названием. OKR работает только если 70% = успех и не наказывается. Премия по OKR — это пицца команде, а не процент от оклада."},
      {"type":"text_block","title":"SMART — как правильно формулировать цель","text":"Любая цель — KPI или OKR — должна быть SMART: Specific (конкретная), Measurable (измеримая), Achievable (достижимая, но амбициозная), Relevant (релевантная), Time-bound (с дедлайном). Плохая цель: «Улучшить продажи». Хорошая SMART: «Увеличить выручку отдела продаж в Сибири на 25% к 31 декабря 2026 за счёт 2 новых менеджеров и партнёрства с 3 поставщиками». В формулировке всё: метрика (выручка), цифра (25%), регион (Сибирь), срок (31.12.2026), инструменты (менеджеры, партнёры)."},
      {"type":"icon_grid","title":"Хорошие vs плохие цели","items":[
        {"icon":"✅","label":"«Конверсия лидов 18% к концу Q2»","desc":"Конкретно, измеримо, с дедлайном"},
        {"icon":"❌","label":"«Стать лучшими»","desc":"Никакого измерения. Когда выполнено? Не понятно"},
        {"icon":"✅","label":"«Сократить срок ответа клиенту с 4 до 1 часа»","desc":"Чёткая метрика и цифра"},
        {"icon":"❌","label":"«Улучшить клиентский сервис»","desc":"Размыто. Что значит «улучшить»? Кто измерит?"},
        {"icon":"✅","label":"«Запустить 3 новых проекта с маржой 18%+»","desc":"Цифры по количеству и качеству"},
        {"icon":"❌","label":"«Развивать новые направления»","desc":"Что значит «развивать»? Когда успешно?"}
      ]},
      {"type":"text_block","title":"Каскадирование — от компании к человеку","text":"OKR (или KPI) компании каскадируется вниз: цель компании = цель отдела = цель сотрудника. Пример. Компания: «Войти в топ-3 строителей Сибири по выручке». Отдел продаж: «Увеличить выручку отдела на 40%». Команда продажников Иркутска: «Найти 8 новых заказчиков с контрактом 10 млн+». Менеджер Иванов: «Закрыть 3 контракта 10+ млн в Иркутске». Каждый уровень видит, как его задача связана с целью компании — это даёт смысл. Без каскадирования цели «висят в воздухе» и непонятно, зачем их делать."},
      {"type":"steps","title":"Цикл управления по OKR — квартальный","items":[
        "Неделя 1 квартала: формулировка OKR на квартал. Топ-менеджмент → отделы → команды → люди",
        "Каждый понедельник: 15-минутное Stand-up с обновлением статуса по ключевым результатам",
        "Раз в 2 недели: ретроспектива и корректировка приоритетов, если ситуация изменилась",
        "Середина квартала (неделя 6-7): mid-cycle check — что идёт хорошо, что плохо, нужны ли изменения",
        "Конец квартала: финальная оценка достижения (% по каждому KR), обсуждение причин",
        "Между кварталами: ретроспектива всей системы — что в ней работает, что менять"
      ]},
      {"type":"warning","level":"warning","text":"OKR без еженедельного обновления статуса — это не OKR, это просто декларация в начале квартала, забытая через 2 недели. 70% всех неудач OKR — это отсутствие еженедельного check-in. Час в понедельник на всю команду — минимум."},
      {"type":"fact_card","icon":"💼","text":"Google — родина OKR (придумали в Intel, масштабировал Google). Их пример квартального OKR команды Search: Objective — «Сделать поиск таким быстрым, чтобы было ощущение мгновенного». Key Results: 1) Снизить медианное время ответа с 250 мс до 100 мс. 2) Снизить 95% перцентиль с 800 мс до 200 мс. 3) Снизить долю запросов >1 сек с 8% до 1%. Достижение по итогам квартала: 80%, 60%, 100%. По OKR-логике это успех (70% — норма). Премии по OKR в Google не привязаны — только базовая зарплата и stock options независимо от achievement."},
      {"type":"fact_card","icon":"📉","text":"2019 год, российская IT-компания (1200 человек) внедрила OKR с привязкой 50% премии. Через полгода: 87% сотрудников ставят OKR заведомо лёгкие (чтобы получить премию). Стратегические амбициозные цели исчезли. Компания отменила OKR, вернулась к KPI. CEO признал: «Мы не услышали базовое правило — OKR без амбиции = KPI с другим названием. Премия убила амбицию». Эта компания потеряла 2 года и 18 млн рублей на консультантов."}
    ]$blocks$::jsonb,
    20, ARRAY['управление','kpi','okr','цели'], false, 'published', 'manual',
    NOW(), CURRENT_DATE
  )
  RETURNING id
)
INSERT INTO office_academy_quiz_questions (lesson_id, sort_order, question_type, question_text, options, correct_explanation)
SELECT lesson.id, q.so, q.qt, q.qtext, q.opts::jsonb, q.expl FROM lesson, (VALUES
  (1, 'choice', 'KPI расшифровывается как:',
   '[{"id":1,"text":"Key Performance Indicator","is_correct":true},{"id":2,"text":"Knowledge Process Integration","is_correct":false},{"id":3,"text":"Key People Initiative","is_correct":false},{"id":4,"text":"Kanban Process Indicator","is_correct":false}]',
   'KPI — Key Performance Indicator, ключевой показатель эффективности. Это конкретная измеримая цифра, которую сотрудник должен достичь за период.'),
  (2, 'choice', 'OKR состоит из:',
   '[{"id":1,"text":"Objective + Outcome","is_correct":false},{"id":2,"text":"Objective + Key Results","is_correct":true},{"id":3,"text":"Organization + KPI + Reward","is_correct":false},{"id":4,"text":"Output + KPI + Review","is_correct":false}]',
   'OKR = Objective (Цель) + Key Results (Ключевые результаты). Один Objective обычно содержит 3-5 Key Results — конкретных измеримых критериев успеха.'),
  (3, 'truefalse', 'Привязка премии к достижению OKR — лучшая практика.',
   '[{"id":1,"text":"Верно","is_correct":false},{"id":2,"text":"Неверно — это убивает амбициозность OKR","is_correct":true}]',
   'Привязка OKR к зарплате — главная ошибка. Если 70% достижение даёт 70% премии, люди ставят лёгкие цели для гарантированной премии. OKR работает только когда 70% = успех и не наказывается финансово.'),
  (4, 'choice', 'Какое достижение OKR считается успехом?',
   '[{"id":1,"text":"100%","is_correct":false},{"id":2,"text":"70%","is_correct":true},{"id":3,"text":"50%","is_correct":false},{"id":4,"text":"30%","is_correct":false}]',
   '70% — это норма успеха OKR. Цель должна быть амбициозной (растягивающей), достижение 100% означает что цель была слишком лёгкой. 30% — мало, надо разобраться в причинах.'),
  (5, 'scenario', 'Тебе как руководителю отдела сказали внедрить OKR с привязкой 30% премии. Что делать?',
   '[{"id":1,"text":"Согласиться — приказ начальства","is_correct":false},{"id":2,"text":"Объяснить риски: привязка к премии убивает амбициозность, предложить альтернативу — KPI для базовых задач + OKR без привязки для стратегии","is_correct":true},{"id":3,"text":"Внедрить, но саботировать","is_correct":false},{"id":4,"text":"Уволиться","is_correct":false}]',
   'Правильное поведение профессионального руководителя — донести риски наверх с аргументами и примерами (пример российской IT-компании потерявшей 2 года). Если приказ остаётся — внедрять с фиксацией возражения в письменном виде. Иногда нужно дать руководству пройти этот опыт самостоятельно.'),
  (6, 'choice', 'Цель «Улучшить продажи» НЕ удовлетворяет какому критерию SMART?',
   '[{"id":1,"text":"Specific (конкретность) и Measurable (измеримость)","is_correct":true},{"id":2,"text":"Time-bound (срок)","is_correct":false},{"id":3,"text":"Только Relevant","is_correct":false},{"id":4,"text":"Achievable","is_correct":false}]',
   '«Улучшить продажи» — не конкретно (на сколько? в каком сегменте?) и не измеримо (как поймём, что выполнено?). Чтобы стать SMART, цель должна быть: «увеличить выручку отдела продаж на 25% к 31 декабря 2026 в регионе Сибирь».'),
  (7, 'choice', 'KPI подходит для:',
   '[{"id":1,"text":"Только новых стартапов","is_correct":false},{"id":2,"text":"Повторяемых задач с измеримыми результатами","is_correct":true},{"id":3,"text":"Любых задач без исключений","is_correct":false},{"id":4,"text":"Только высшего руководства","is_correct":false}]',
   'KPI работает там, где задача повторяемая (продажи, производство, обработка заявок) и результат измерим в цифрах. Для новых направлений с неопределённым результатом лучше OKR.'),
  (8, 'truefalse', 'OKR работают без еженедельного обновления статуса.',
   '[{"id":1,"text":"Верно","is_correct":false},{"id":2,"text":"Неверно — 70% провалов OKR от отсутствия check-in","is_correct":true}]',
   'OKR без еженедельного обновления статуса = декларация, забытая через 2 недели. Stand-up в понедельник на 15 минут — обязательный минимум. По статистике 70% всех провалов OKR — это отсутствие регулярного check-in.'),
  (9, 'scenario', 'Команда выполнила OKR на 90% (цифры близко к цели). Что делать в следующем квартале?',
   '[{"id":1,"text":"Поставить такие же цели — работает же","is_correct":false},{"id":2,"text":"Поставить более амбициозные — 90% значит цель была недостаточно растягивающей","is_correct":true},{"id":3,"text":"Поставить лёгкие цели — расслабиться","is_correct":false},{"id":4,"text":"Отменить OKR","is_correct":false}]',
   '90% достижение OKR — это сигнал что цель была недостаточно амбициозной. Если по правилу OKR 70% = успех, то 90% значит «можно было замахнуться больше». В следующем квартале — растянуть цель, например +30% или +50% к показателю.'),
  (10, 'choice', 'Каскадирование целей означает:',
   '[{"id":1,"text":"Цели компании = цели отделов = цели людей","is_correct":true},{"id":2,"text":"Цели меняются каждый день","is_correct":false},{"id":3,"text":"Цели одинаковы у всех сотрудников","is_correct":false},{"id":4,"text":"Цели ставит только начальник","is_correct":false}]',
   'Каскадирование — это связь целей разных уровней. Цель компании реализуется через цели отделов, которые реализуются через цели команд, которые реализуются через цели людей. Без каскадирования сотрудники не понимают, зачем их задачи нужны.')
) AS q(so, qt, qtext, opts, expl);


-- ════════════════════════════════════════════════════════════════════════════
-- ALL — Информационная безопасность: фишинг, пароли, MFA, утечки
-- ════════════════════════════════════════════════════════════════════════════

WITH lesson AS (
  INSERT INTO office_academy_lessons
    (month_number, track, title, saga, cover_icon, cover_color,
     blocks, estimated_minutes, tags, is_mandatory, status, generated_by,
     published_at, release_date)
  VALUES (
    7, 'all', 'Инфобезопасность: фишинг, пароли, MFA, утечки',
    'Цифровая броня', '🔒', '#18202e',
    $blocks$[
      {"type":"cover","icon":"🔒","title":"Инфобезопасность: фишинг, пароли, MFA, утечки","subtitle":"Один кликнул на ссылку из письма — потеряли 12 млн. Как этого не допустить"},
      {"type":"intro","text":"Кибератаки — это не «проблема ИТ-отдела». 90% успешных атак начинаются с обычного сотрудника, который кликнул на ссылку в письме, открыл подозрительный файл или продиктовал пароль по телефону «службе безопасности банка». ИТ-отдел может поставить любые антивирусы, но если ты сам отдал хакерам логин — они уже внутри. Эта лекция — практическая инструкция: что узнать и что НЕ делать каждый рабочий день."},
      {"type":"text_block","title":"Фишинг — почему он работает","text":"Фишинг — это попытка обмануть человека, чтобы он сам отдал данные (пароли, банковские реквизиты, коды из СМС) или установил вредоносное ПО. 95% всех успешных кибератак начинаются с фишинга. Почему работает: 1) Психология срочности — «срочно ответьте, иначе доступ заблокируют». 2) Имитация авторитета — «от имени банка», «от ФНС», «от службы безопасности». 3) Любопытство — «новая видеозапись с вами», «зарплатная ведомость». 4) Страх — «уголовное дело», «штраф 50 000». Современные фишинговые письма практически неотличимы от настоящих — копируется логотип, домен похож (вместо asgard-crm.ru — asgard.crm.ru или asgardcrm.ru), стиль письма."},
      {"type":"icon_grid","title":"Типичные фишинговые письма — как узнать","items":[
        {"icon":"📧","label":"От «банка» о блокировке","desc":"«Ваш счёт заблокирован, подтвердите данные» — звонок в банк, никогда по ссылке"},
        {"icon":"📨","label":"От «ФНС» о штрафе","desc":"«Уголовное дело за неуплату» — звонок в ФНС по официальному номеру"},
        {"icon":"💰","label":"От «начальника» о переводе","desc":"«Срочно переведи 500 тыс, расскажу потом» — звонок напрямую"},
        {"icon":"📦","label":"От «доставки»","desc":"«Ваша посылка не доставлена, перейдите по ссылке» — войти в личный кабинет сайта"},
        {"icon":"🎁","label":"От «службы IT»","desc":"«Срочное обновление пароля» — звонок в IT-отдел напрямую"},
        {"icon":"📞","label":"СМС с кодом","desc":"«Вам пришёл код, никому не сообщайте» — НЕ сообщать ни службам, ни «начальству»"}
      ]},
      {"type":"text_block","title":"Признаки фишингового письма — чек-лист","text":"Адрес отправителя выглядит похоже, но не точно: asgard-crm.ru vs asgard.crm.ru, sberbank.ru vs sberbahk.ru (одна буква). Атмосфера срочности — «срочно», «немедленно», «иначе будет последствие». Просьба перейти по ссылке и ввести логин/пароль. Просьба сообщить код из СМС или скачать прикреплённый файл. Орфографические ошибки в письме (хотя последние годы их всё меньше). Логотип чуть-чуть отличается. Письмо от человека/службы, с которой вы никогда не общались. Любой из этих признаков — повод НЕ кликать ничего и спросить у IT или у указанного отправителя по другому каналу."},
      {"type":"warning","level":"danger","text":"Никогда, ни при каких обстоятельствах не вводите свой рабочий пароль на странице, на которую перешли из письма. Если пришло письмо «обновить пароль», открыть браузер вручную → ввести адрес asgard-crm.ru → войти. Никогда по ссылке из письма. Это правило закрывает 80% фишинговых атак."},
      {"type":"text_block","title":"Пароли — как сделать правильно","text":"Главное правило паролей 2026: ДЛИНА важнее СЛОЖНОСТИ. Пароль «correcthorsebatterystaple» (4 случайных слова) надёжнее, чем «Tr1cky!23». Длина минимум 16 символов. Никаких личных данных (дата рождения, имя ребёнка). Уникальный для каждого сервиса (рабочий, личный, банк) — иначе утечка одного пароля компрометирует всё. Хранить — в менеджере паролей (KeePassXC бесплатно, Bitwarden бесплатно, 1Password платно). Не записывать на бумажке возле компьютера. Не отправлять в Telegram/WhatsApp/email. Не диктовать по телефону «службе безопасности» — никогда никакая служба не просит пароль."},
      {"type":"icon_grid","title":"Хороший пароль vs плохой","items":[
        {"icon":"✅","label":"correct horse battery staple +2026","desc":"32 символа, легко запомнить, невозможно угадать"},
        {"icon":"✅","label":"MyDog$Loves$Tundra_Walks_2026","desc":"30 символов, личное, но не очевидное"},
        {"icon":"❌","label":"Password123!","desc":"В словарях хакеров миллион вариантов"},
        {"icon":"❌","label":"Ivan1985","desc":"Имя + дата = 5 минут перебора"},
        {"icon":"❌","label":"Qwerty123","desc":"В первой сотне самых популярных паролей"},
        {"icon":"❌","label":"Тот же пароль везде","desc":"Утечка одного сайта = взлом банка, почты, работы"}
      ]},
      {"type":"text_block","title":"MFA — двухфакторная аутентификация","text":"MFA (Multi-Factor Authentication) — это вход в систему по двум факторам: пароль + ещё что-то. Чаще всего «ещё что-то» — это код из мобильного приложения (Google Authenticator, Microsoft Authenticator, FreeOTP) или СМС на телефон. Преимущество: даже если хакер украдёт пароль, без второго фактора он не войдёт. По статистике MFA блокирует 99.9% автоматических взломов. Включить MFA нужно ВЕЗДЕ: рабочая почта, личная почта, банки, госуслуги, асгард-CRM, любые сервисы где есть ваши данные. Это занимает 2 минуты на сервис, экономит миллионы."},
      {"type":"warning","level":"warning","text":"СМС-MFA НЕ самый безопасный вариант. Атаки SIM-swap (мошенник убеждает оператора связи перевыпустить SIM-карту на себя) обходят СМС. Если есть выбор — использовать MFA через приложение (Google Authenticator, FreeOTP). Если только СМС — установить у оператора запрет на перевыпуск SIM без личного присутствия в офисе."},
      {"type":"steps","title":"Алгоритм при подозрении на фишинг","items":[
        "НЕ кликать на ссылку, НЕ скачивать файл, НЕ отвечать письмом",
        "Сделать скриншот письма со всеми деталями (включая полный адрес отправителя)",
        "Переслать письмо в ИТ-отдел или ответственному за инфобезопасность",
        "Если уже кликнули — немедленно сообщить IT (это не повод для увольнения, это вопрос времени реакции)",
        "Если ввели пароль — немедленно сменить пароль на всех сервисах, где использовался похожий",
        "Если открыли вложенный файл — НЕ работать на этом компьютере, отключить от сети, сообщить IT"
      ]},
      {"type":"text_block","title":"Утечки данных — что делать","text":"Утечки баз данных публикуются регулярно. Сайт haveibeenpwned.com позволяет проверить, утёк ли ваш email в одной из 800+ известных утечек. Если утёк — все пароли, использованные с этим email, считаются скомпрометированными. Менять немедленно, начиная с банков и рабочих сервисов. У Асгарда есть внутренняя политика: при обнаружении утечки рабочего email/пароля сотрудник обязан в течение 24 часов: сменить пароль, включить MFA если не было, сообщить в IT. Утечки бывают и у самой компании — например, через скомпрометированный аккаунт сотрудника. Поэтому каждый сотрудник — это часть периметра защиты."},
      {"type":"fact_card","icon":"💀","text":"Январь 2024 года, российская транспортная компания (350 человек). Главный бухгалтер получил «срочное письмо от директора» — переведи 12.5 млн руб поставщику, реквизиты в приложении. Адрес был «директора», но с одной буквой отличия: имя_фамилия@kompaniya.ru → имя_фамилiя@kompaniya.ru (кириллическая i). Бухгалтер не заметил, перевёл. Деньги ушли на счёт хакеров в Турции, обналичены за 6 часов. Возврат невозможен. Расследование показало: атака готовилась 3 недели, хакеры читали корпоративную почту директора через скомпрометированный пароль, скопировали стиль, выбрали момент когда директор в командировке. Бухгалтер не уволен (помог следствию), но компания потеряла 12.5 млн навсегда. Урок: при любом переводе крупной суммы — звонок директору голосом."},
      {"type":"fact_card","icon":"🛡️","text":"Сбербанк ввёл «период подтверждения» для крупных переводов: при переводе > 600 тыс руб система требует 2-минутную паузу + видеоподтверждение в приложении. За 2 года эта мера предотвратила 23 тыс попыток мошеннических переводов на сумму 4.8 млрд руб. Технически просто, психологически работает: 2 минуты дают человеку время «отойти от паники» и понять, что его обманывают."}
    ]$blocks$::jsonb,
    20, ARRAY['безопасность','фишинг','пароли','утечки'], true, 'published', 'manual',
    NOW(), CURRENT_DATE
  )
  RETURNING id
)
INSERT INTO office_academy_quiz_questions (lesson_id, sort_order, question_type, question_text, options, correct_explanation)
SELECT lesson.id, q.so, q.qt, q.qtext, q.opts::jsonb, q.expl FROM lesson, (VALUES
  (1, 'choice', 'Какой процент успешных кибератак начинается с фишинга?',
   '[{"id":1,"text":"30%","is_correct":false},{"id":2,"text":"60%","is_correct":false},{"id":3,"text":"95%","is_correct":true},{"id":4,"text":"100%","is_correct":false}]',
   '95% успешных кибератак начинаются с фишинга — обманом сотрудника, который сам отдаёт данные или открывает вредоносный файл. Технические защиты (антивирусы, файрволы) бессильны против человеческой ошибки.'),
  (2, 'choice', 'Что важнее в пароле — длина или сложность?',
   '[{"id":1,"text":"Сложность с символами и цифрами","is_correct":false},{"id":2,"text":"Длина — 16+ символов важнее","is_correct":true},{"id":3,"text":"Только цифры","is_correct":false},{"id":4,"text":"Только буквы","is_correct":false}]',
   'Длина важнее сложности. Пароль «correcthorsebatterystaple» (4 случайных слова, 26 символов) надёжнее, чем «Tr1cky!23» (9 символов). Хакеры подбирают пароли через словари — короткие сложные ломаются быстрее длинных «осмысленных».'),
  (3, 'truefalse', 'Использовать один и тот же пароль на работе и в личной почте — нормально.',
   '[{"id":1,"text":"Верно","is_correct":false},{"id":2,"text":"Неверно — утечка одного скомпрометирует всё","is_correct":true}]',
   'Никогда не использовать один пароль на разных сервисах. Если утечёт база одного сайта (а утечки случаются регулярно), все ваши аккаунты с тем же паролем становятся уязвимы. Хакеры автоматически проверяют утёкшие пары email+пароль на 100+ популярных сервисах.'),
  (4, 'choice', 'MFA блокирует какой процент автоматических взломов?',
   '[{"id":1,"text":"50%","is_correct":false},{"id":2,"text":"75%","is_correct":false},{"id":3,"text":"99.9%","is_correct":true},{"id":4,"text":"100%","is_correct":false}]',
   '99.9% — это статистика Microsoft и Google. Даже если хакер украл пароль, без второго фактора (код из приложения или СМС) он не войдёт. 2 минуты на включение MFA — лучшая инвестиция в безопасность.'),
  (5, 'scenario', 'Приходит письмо «от директора»: «Срочно переведи 800 тыс поставщику, реквизиты в приложении, я в самолёте, не могу позвонить». Что делаешь?',
   '[{"id":1,"text":"Перевести — директор сказал срочно","is_correct":false},{"id":2,"text":"Позвонить директору на личный номер, голосом подтвердить. Если не отвечает — отложить","is_correct":true},{"id":3,"text":"Перевести, потом позвонить","is_correct":false},{"id":4,"text":"Спросить у IT","is_correct":false}]',
   'Любая крупная сумма — звонок директору голосом на известный номер. Письмо может быть от хакера (как пример 12.5 млн в лекции). Психология срочности — главная техника хакеров. Профессиональный бухгалтер ставит правило: 800+ тыс = звонок голосом, без исключений. Лучше задержать перевод на 1 час, чем потерять деньги навсегда.'),
  (6, 'choice', 'Самый надёжный вид MFA:',
   '[{"id":1,"text":"СМС-код","is_correct":false},{"id":2,"text":"Код из приложения (Google Authenticator, FreeOTP)","is_correct":true},{"id":3,"text":"Контрольный вопрос","is_correct":false},{"id":4,"text":"Девичья фамилия матери","is_correct":false}]',
   'Приложение-аутентификатор — наиболее безопасно. Коды генерируются локально на телефоне без передачи через интернет. СМС уязвим к SIM-swap атакам. Контрольные вопросы — катастрофа (девичью фамилию матери можно найти в соцсетях).'),
  (7, 'truefalse', 'Можно сообщить код из СМС «службе безопасности банка», которая позвонила.',
   '[{"id":1,"text":"Верно","is_correct":false},{"id":2,"text":"Неверно — это всегда мошенники","is_correct":true}]',
   'НИКОГДА не сообщать код из СМС никому. Настоящий банк никогда не просит код по телефону — это правило 100% мошенничества. Любой звонок «службы безопасности» с просьбой назвать код — мошенник. Сразу класть трубку и звонить в банк по номеру с банковской карты.'),
  (8, 'scenario', 'Ты кликнул на ссылку в письме, открылась страница входа в asgard-crm. Похожа на обычную. Что делать?',
   '[{"id":1,"text":"Ввести пароль — страница же похожа","is_correct":false},{"id":2,"text":"НЕ вводить ничего, закрыть, открыть браузер вручную, ввести адрес — это правильный путь к сайту","is_correct":true},{"id":3,"text":"Ввести только логин, без пароля","is_correct":false},{"id":4,"text":"Ввести неправильный пароль для проверки","is_correct":false}]',
   'Фишинговая страница может выглядеть как настоящая, но её URL отличается (asgard.crm.ru вместо asgard-crm.ru). Введёшь пароль — он попадёт хакерам. Правило: пароль вводим только на странице, которую открыли вручную через адресную строку. Никогда не по ссылке из письма.'),
  (9, 'choice', 'Где хранить пароли?',
   '[{"id":1,"text":"На бумажке возле компьютера","is_correct":false},{"id":2,"text":"В менеджере паролей (KeePassXC, Bitwarden)","is_correct":true},{"id":3,"text":"В Excel-файле на рабочем столе","is_correct":false},{"id":4,"text":"В Telegram «в избранном»","is_correct":false}]',
   'Менеджер паролей — единственный безопасный способ. KeePassXC и Bitwarden бесплатные. Excel-файл легко украсть, Telegram-избранное доступно если украдут аккаунт, бумажка возле компьютера — её увидят все. Менеджер шифрует пароли мастер-паролем.'),
  (10, 'truefalse', 'Если случайно кликнул на фишинговую ссылку — нужно молчать, чтобы не уволили.',
   '[{"id":1,"text":"Верно","is_correct":false},{"id":2,"text":"Неверно — немедленно сообщить IT, скорость реакции важнее","is_correct":true}]',
   'Кликнул — сразу IT. Это НЕ повод для увольнения, это вопрос времени реакции. Если IT-отдел узнает за 5 минут, можно изолировать проблему. Если узнают через сутки — взлом уже распространился. Никто не увольняет за «кликнул», увольняют за «скрыл». Молчание превращает мелкий инцидент в катастрофу.')
) AS q(so, qt, qtext, opts, expl);


-- ════════════════════════════════════════════════════════════════════════════
-- PM (новый, продолжение V147) — Управление рисками проекта
-- ════════════════════════════════════════════════════════════════════════════

WITH lesson AS (
  INSERT INTO office_academy_lessons
    (month_number, track, title, saga, cover_icon, cover_color,
     blocks, estimated_minutes, tags, is_mandatory, status, generated_by,
     published_at, release_date)
  VALUES (
    14, 'pm', 'Управление рисками: реестр, mitigation, эскалация',
    'Искусство руководства', '⚠️', '#1e2840',
    $blocks$[
      {"type":"cover","icon":"⚠️","title":"Управление рисками: реестр, mitigation, эскалация","subtitle":"Почему «всё под контролем» — главная фраза перед провалом"},
      {"type":"intro","text":"Менеджер проекта без реестра рисков — это водитель без зеркал. Он видит только то, что прямо перед ним, и не видит надвигающейся аварии. По исследованию PMI 2024 года, 67% сорванных проектов имеют общую причину: риски не были идентифицированы и записаны. Не отсутствие плана действий, а отсутствие самого СПИСКА того, что может пойти не так. Эта лекция — практическая система управления рисками за 30 минут в неделю."},
      {"type":"text_block","title":"Что такое риск и как его определить","text":"Риск — это событие, которое МОЖЕТ произойти и повлияет на проект (плохо или хорошо). Ключевое слово — «может», не «точно произойдёт». Если событие точно произойдёт — это уже не риск, это проблема. У каждого риска две оси: вероятность (от 1 до 5) и влияние (от 1 до 5). Произведение даёт балл риска: 1 (низкий) — 25 (критический). Не все риски одинаковы — высокая вероятность но малое влияние (поставщик опоздал на день — переждали) и низкая вероятность но катастрофическое влияние (пожар на объекте — потеря всего) требуют разной реакции."},
      {"type":"icon_grid","title":"Категории рисков на стройке","items":[
        {"icon":"🌪️","label":"Внешние / погодные","desc":"Шторм, ливень, мороз. Срыв сроков. Страхуется"},
        {"icon":"👥","label":"Кадровые","desc":"Уход ключевого сотрудника, болезнь бригадира. Резерв людей"},
        {"icon":"🚚","label":"Поставки","desc":"Задержка материала, отказ поставщика. Двойные источники"},
        {"icon":"💰","label":"Финансовые","desc":"Задержка оплаты заказчика, удорожание материалов. Резервы"},
        {"icon":"⚖️","label":"Регуляторные","desc":"Изменение норм, отзыв лицензии. Мониторинг законов"},
        {"icon":"🔥","label":"Технические","desc":"Авария оборудования, ошибка проекта. Подрядчики, страховка"}
      ]},
      {"type":"text_block","title":"Реестр рисков — главный документ PM","text":"Реестр рисков — это просто таблица в Excel или CRM. Колонки: ID риска, описание, категория, вероятность (1-5), влияние (1-5), балл (произведение), ответственный, план снижения (mitigation), план реагирования (если случится), статус, дата последнего обзора. Реестр ведётся для КАЖДОГО проекта от старта. Обновляется еженедельно. Должен содержать минимум 15-25 рисков для среднего проекта — если у вас 3 риска в реестре, вы недостаточно подумали."},
      {"type":"text_block","title":"Mitigation и Response — две стратегии","text":"Mitigation (снижение) — это что мы делаем СЕЙЧАС, чтобы вероятность или влияние риска уменьшились. Например: риск «уход бригадира». Mitigation: повысить зарплату, найти стажёра-замену, документировать ноу-хау. Response (реагирование) — это что мы делаем ЕСЛИ риск реализовался. Например: бригадир ушёл. Response: ввести стажёра-зама, нанять временного подрядчика, перераспределить нагрузку. Хороший PM прорабатывает оба плана для топ-10 рисков, средний — только response, плохой — никакой."},
      {"type":"icon_grid","title":"4 стратегии работы с риском","items":[
        {"icon":"❌","label":"Избежать (Avoid)","desc":"Не делать этой работы вообще. Снижает риск до 0"},
        {"icon":"📉","label":"Снизить (Mitigate)","desc":"Уменьшить вероятность или влияние. Большинство рисков"},
        {"icon":"🛡️","label":"Передать (Transfer)","desc":"Страховка, подрядчик, гарантия. Риск на третьем лице"},
        {"icon":"✅","label":"Принять (Accept)","desc":"Сознательное согласие на риск. Малое влияние или дорого избежать"}
      ]},
      {"type":"warning","level":"danger","text":"Самая опасная стратегия — «забыть про риск». Это формальный «Accept» без обсуждения. Если риск был в реестре с баллом 12, и его «приняли», но не зафиксировали почему — это бомба. Через 3 месяца риск реализуется, и никто не помнит, что обсуждали и решали."},
      {"type":"text_block","title":"Эскалация — когда поднимать к директору","text":"Не каждый риск идёт к директору — иначе он будет утопает в мелочах. Правило эскалации: риски с баллом ≥15 + риски выше полномочий PM по бюджету или стратегии. Например: риск «потеря заказчика А» (балл 20) — к директору. Риск «опоздание поставщика на 2 дня» (балл 6) — решает PM. Эскалация не в формате «у нас проблема, что делать?», а в формате «вот риск, вот варианты решений, рекомендую вариант B, нужно решение». Это позиция взрослого менеджера, а не паникёра."},
      {"type":"steps","title":"Еженедельный обзор рисков — 30 минут","items":[
        "Открыть реестр рисков. Пройти по ТОП-5 (с самым высоким баллом)",
        "По каждому — что изменилось за неделю? Mitigation работает? Балл изменился?",
        "Появились ли новые риски? Записать в реестр",
        "Стали ли какие-то риски проблемами (точно произойдут)? Переместить в issue log",
        "Есть ли риски, требующие эскалации? Подготовить материал для директора",
        "Обновить статус каждого риска (открыт / на mitigation / эскалирован / закрыт)",
        "Если несколько мелких рисков от одного источника — объединить в один крупный с категорией"
      ]},
      {"type":"fact_card","icon":"📊","text":"NASA после катастрофы Challenger в 1986 году внедрила систему «risk-based decision making». Каждое решение оценивается через призму рисков. Перед запуском любого аппарата команда проходит «risk review» где КАЖДЫЙ инженер ОБЯЗАН назвать минимум 3 риска. Если ты не нашёл рисков — ты либо не разбираешься, либо что-то скрываешь. Эта культура изменила отношение к рискам с «не паникуй» к «рассказывай что видишь». Количество запусков выросло в 2.3 раза, аварийность снизилась в 7 раз."},
      {"type":"fact_card","icon":"💼","text":"2023 год, строительный холдинг в Москве. PM Андрей вёл реестр рисков по проекту 180 млн. Записал риск «удорожание арматуры >30% к лету» с баллом 16. Mitigation: подписать долгосрочный договор с поставщиком сейчас. Директор отклонил («дорого, привязка цены»). Через 4 месяца цены выросли на 42%, проект просел на 24 млн. Андрей показал директору запись риска в реестре — переписку и отказ. Не уволили, наоборот повысили: «Этот PM работает по системе, виноват я». Реестр рисков — это и личная защита тоже."}
    ]$blocks$::jsonb,
    20, ARRAY['риски','реестр','эскалация','pm'], false, 'published', 'manual',
    NOW(), CURRENT_DATE
  )
  RETURNING id
)
INSERT INTO office_academy_quiz_questions (lesson_id, sort_order, question_type, question_text, options, correct_explanation)
SELECT lesson.id, q.so, q.qt, q.qtext, q.opts::jsonb, q.expl FROM lesson, (VALUES
  (1, 'choice', 'Чем риск отличается от проблемы?',
   '[{"id":1,"text":"Риск опаснее проблемы","is_correct":false},{"id":2,"text":"Риск — может произойти, проблема — уже произошла","is_correct":true},{"id":3,"text":"Это одно и то же","is_correct":false},{"id":4,"text":"Риск решает PM, проблему — директор","is_correct":false}]',
   'Риск — событие, которое МОЖЕТ произойти. Проблема — уже произошедшее событие. Реестр рисков — для возможного, issue log — для случившегося. Когда риск реализуется, он переходит из реестра рисков в issue log.'),
  (2, 'choice', 'Балл риска считается как:',
   '[{"id":1,"text":"Только вероятность","is_correct":false},{"id":2,"text":"Только влияние","is_correct":false},{"id":3,"text":"Вероятность × влияние","is_correct":true},{"id":4,"text":"Среднее арифметическое","is_correct":false}]',
   'Балл риска = вероятность × влияние, обе шкалы 1-5. Максимум 25 (критический), минимум 1 (низкий). Это позволяет приоритизировать риски и сосредоточиться на самых важных.'),
  (3, 'truefalse', 'Хороший реестр рисков для среднего проекта — 3 риска.',
   '[{"id":1,"text":"Верно","is_correct":false},{"id":2,"text":"Неверно — минимум 15-25","is_correct":true}]',
   '3 риска в реестре — это сигнал, что вы недостаточно подумали о проекте. Средний проект имеет 15-25 рисков разных категорий (внешние, кадровые, поставки, финансовые, регуляторные, технические).'),
  (4, 'choice', 'Mitigation — это:',
   '[{"id":1,"text":"План действий когда риск произошёл","is_correct":false},{"id":2,"text":"Действия СЕЙЧАС для снижения вероятности или влияния","is_correct":true},{"id":3,"text":"Эскалация директору","is_correct":false},{"id":4,"text":"Страхование","is_correct":false}]',
   'Mitigation — это снижение риска ЗАРАНЕЕ. Что мы делаем сейчас, чтобы вероятность или влияние стали меньше. План действий ЕСЛИ риск случился — это Response (реагирование). Хороший PM прорабатывает оба плана.'),
  (5, 'scenario', 'Риск «уход ключевого бригадира» с баллом 16. Какой план mitigation правильный?',
   '[{"id":1,"text":"Запретить ему увольняться","is_correct":false},{"id":2,"text":"Повысить зарплату, документировать ноу-хау, подготовить замену из стажёров","is_correct":true},{"id":3,"text":"Не делать ничего, дождаться когда уйдёт","is_correct":false},{"id":4,"text":"Эскалировать директору без плана","is_correct":false}]',
   'Mitigation для риска ухода ключевого человека — комплекс: финансовая мотивация (зарплата), снижение зависимости от него (документация ноу-хау), подготовка замены (стажёры). Запрет уволиться невозможен. Бездействие — это «забыть про риск», самая опасная стратегия.'),
  (6, 'choice', 'При балле риска ≥15 нужно:',
   '[{"id":1,"text":"Только записать в реестр","is_correct":false},{"id":2,"text":"Эскалировать директору с вариантами решений","is_correct":true},{"id":3,"text":"Игнорировать","is_correct":false},{"id":4,"text":"Передать клиенту","is_correct":false}]',
   'Риски с баллом ≥15 (вероятность 4-5 × влияние 3-4) требуют эскалации к директору. Эскалация в формате «вот риск, вот варианты, рекомендую B, нужно решение» — позиция взрослого менеджера, а не паникёра «у нас проблема, что делать».'),
  (7, 'truefalse', 'Если риск принят (Accept) — можно его не записывать в реестр.',
   '[{"id":1,"text":"Верно","is_correct":false},{"id":2,"text":"Неверно — обязательно записать с обоснованием","is_correct":true}]',
   'Любое принятое решение по риску фиксируется в реестре с обоснованием. «Забыть про риск» — самая опасная стратегия. Через 3 месяца риск реализуется, никто не помнит обсуждение, паника. Фиксация защищает PM лично.'),
  (8, 'scenario', 'У вас сорвался риск, которого не было в реестре. Что делать сначала?',
   '[{"id":1,"text":"Скрыть от руководства","is_correct":false},{"id":2,"text":"Решить проблему + добавить риск в реестр + проанализировать почему пропустили","is_correct":true},{"id":3,"text":"Уволить себя","is_correct":false},{"id":4,"text":"Винить команду","is_correct":false}]',
   'Сначала решить (это уже проблема, не риск). Потом обязательно добавить в реестр + сделать lessons learned: почему пропустили? Какие классы рисков мы не рассматривали? Это позволит избежать повторов. Скрытие — катастрофа: через месяц повторится.'),
  (9, 'choice', 'Какая стратегия означает «передать риск другому»?',
   '[{"id":1,"text":"Avoid","is_correct":false},{"id":2,"text":"Mitigate","is_correct":false},{"id":3,"text":"Transfer (страховка, подрядчик)","is_correct":true},{"id":4,"text":"Accept","is_correct":false}]',
   'Transfer — передача риска третьему лицу. Страхование, привлечение подрядчика с фиксированной ценой, гарантии поставщика. Риск остаётся, но финансовые последствия покрывает третья сторона. Полезно для рисков с большим влиянием но низкой вероятностью.'),
  (10, 'truefalse', 'Реестр рисков нужно обновлять только в начале проекта.',
   '[{"id":1,"text":"Верно","is_correct":false},{"id":2,"text":"Неверно — еженедельно","is_correct":true}]',
   'Реестр рисков — живой документ. Еженедельный обзор 30 минут: новые риски, изменения по существующим, эскалации. Без регулярного обновления реестр устаревает за месяц и становится формальностью.')
) AS q(so, qt, qtext, opts, expl);


-- ════════════════════════════════════════════════════════════════════════════
-- HR (новый, продолжение V148) — Сложные разговоры: выговор, увольнение, фидбек
-- ════════════════════════════════════════════════════════════════════════════

WITH lesson AS (
  INSERT INTO office_academy_lessons
    (month_number, track, title, saga, cover_icon, cover_color,
     blocks, estimated_minutes, tags, is_mandatory, status, generated_by,
     published_at, release_date)
  VALUES (
    14, 'hr', 'Сложные разговоры: выговор, увольнение, фидбек',
    'Кадровое дело', '🗣️', '#1e3830',
    $blocks$[
      {"type":"cover","icon":"🗣️","title":"Сложные разговоры: выговор, увольнение, фидбек","subtitle":"Почему 80% увольнений превращаются в скандал — и как этого избежать"},
      {"type":"intro","text":"Каждый менеджер боится «того самого разговора». Уволить, сделать выговор, дать жёсткий фидбек. Из-за этого страха разговоры либо откладываются (проблема растёт), либо проводятся плохо (скандал, суд, увольнение по статье). Эта лекция — не про мотивационные книжки, а про практическую структуру: что говорить, в какой последовательности, чего НЕ делать. Применимо к любой роли — PM, директор, HR."},
      {"type":"text_block","title":"Три типа сложных разговоров","text":"1) Корректирующий фидбек — указать сотруднику на конкретное поведение, которое нужно изменить. Это не наказание, это обучение. Хороший фидбек убирает 90% проблем до того, как они станут серьёзными. 2) Дисциплинарное взыскание — формальная санкция (выговор) за повторяющееся нарушение. Документируется приказом, может стать основой увольнения. 3) Увольнение — расторжение трудового договора. Самый сложный разговор, потому что меняет жизнь человека. Каждый тип требует своей структуры, и смешивать их нельзя. «Я тебя предупреждаю и сразу увольняю» — пример всех ошибок сразу."},
      {"type":"text_block","title":"Корректирующий фидбек — модель SBI","text":"SBI — Situation, Behavior, Impact. Ситуация: где и когда произошло (конкретно, не «обычно»). Поведение: что человек сделал (наблюдаемое действие, не интерпретация). Влияние: что это вызвало (на команду, проект, заказчика). Пример плохого фидбека: «Ты невнимательный». Пример хорошего по SBI: «Вчера на совещании с заказчиком (Ситуация) ты несколько раз перебивал главного инженера (Поведение). Заказчик отметил это в кулуарах как непрофессионально — мы можем потерять следующий тендер (Влияние). Что произошло?» Последний вопрос важен: даём собеседнику возможность объяснить, может быть мы не знаем контекст."},
      {"type":"icon_grid","title":"Главные ошибки фидбека","items":[
        {"icon":"❌","label":"«Ты всегда / никогда…»","desc":"Обобщения вызывают защиту. Конкретный случай"},
        {"icon":"❌","label":"Личная оценка («ты ленивый»)","desc":"Поведение, а не характеристика человека"},
        {"icon":"❌","label":"Публично при коллегах","desc":"Унижение. Фидбек один на один"},
        {"icon":"❌","label":"Через неделю после события","desc":"Свежо. Чем позже, тем менее эффективно"},
        {"icon":"❌","label":"Только негатив без позитива","desc":"Контекст: 80/20 хороший/корректирующий"},
        {"icon":"❌","label":"«Что ты об этом думаешь?» в конце","desc":"Закрытый вопрос. Лучше «Как мы изменим это?»"}
      ]},
      {"type":"warning","level":"warning","text":"Худшая практика — копить негативный фидбек на годовой review. Когда раз в год вываливаешь на сотрудника список претензий за 12 месяцев, он не может ничего изменить (всё в прошлом) и просто получает удар. Регулярный фидбек (раз в 2-4 недели) маленькими порциями работает в 10 раз лучше."},
      {"type":"text_block","title":"Дисциплинарное взыскание — структура встречи","text":"Дисциплинарка — это формальное действие по Трудовому кодексу (ст. 192-193 ТК РФ). Перед встречей обязательно: документально зафиксировано нарушение (акт, докладная), запрошены письменные объяснения сотрудника, в течение 1 месяца с момента обнаружения. Структура самой встречи: 1) Озвучить факты (конкретные даты, действия). 2) Зачитать письменные объяснения, если есть. 3) Объявить взыскание (замечание, выговор, увольнение по соответствующему основанию). 4) Дать копию приказа, подпись об ознакомлении. 5) Сказать о следующих шагах: если повторится — следующее по тяжести. Без эмоций, без личных оценок, без обсуждения. Это формальная процедура."},
      {"type":"text_block","title":"Увольнение — три сценария","text":"1) По соглашению сторон (ст. 78 ТК). Самый цивилизованный путь: договариваемся об условиях (компенсация, дата), подписываем соглашение, расходимся без обид. Подходит когда обе стороны хотят прекратить. 2) По собственному желанию (ст. 80 ТК). Сотрудник пишет заявление, 2 недели отработки. Подходит когда сотрудник готов уйти сам. 3) По инициативе работодателя (ст. 81 ТК). Сложно: нужны основания (сокращение, нарушения, несоответствие должности), процедуры (предупреждения, комиссии), компенсации. Часто оспаривается в суде. Стратегия: всегда стараться о соглашении сторон с разумной компенсацией. Дешевле, быстрее, без репутационных рисков."},
      {"type":"icon_grid","title":"Сравнение оснований увольнения","items":[
        {"icon":"🤝","label":"Соглашение сторон","desc":"1-3 оклада компенсация. Дёшево, быстро, без рисков"},
        {"icon":"📝","label":"По собственному желанию","desc":"Без компенсации. 2 недели отработки. Если сотрудник согласен"},
        {"icon":"📉","label":"Сокращение","desc":"2-5 окладов + 2 мес. предупреждение. Дорого, но законно"},
        {"icon":"⚠️","label":"За нарушения (выговор + повторное)","desc":"Без компенсации. Высокий риск суда (50% проигрывают)"},
        {"icon":"❌","label":"За один грубый проступок","desc":"Прогул, опьянение, кража. Тщательная фиксация — обязательна"}
      ]},
      {"type":"steps","title":"Алгоритм разговора об увольнении","items":[
        "Подготовка: документы готовы, причина чёткая, условия согласованы с HR и юристом",
        "Встреча в закрытой переговорке, время — утром понедельника или вторника (НЕ вечер пятницы)",
        "Прямо к делу за 30 секунд: «Иван, у нас не получается, мы расстаёмся. Хотел бы предложить соглашение сторон»",
        "Назвать условия: дата прекращения, компенсация, формат рекомендаций, возврат имущества",
        "Дать время на реакцию (5-10 минут пауза). НЕ убеждать, НЕ оправдываться. Молчание — нормально",
        "Ответить на вопросы по фактам. Не обсуждать «почему именно я» — это не помогает",
        "Дать копию соглашения, дать время до конца дня подумать. НЕ давить на подпись",
        "После: помочь практически (передача дел, рекомендация, контакты HR-партнёров)"
      ]},
      {"type":"warning","level":"danger","text":"НИКОГДА не увольнять по эмоциям сразу после конфликта. Решение об увольнении принимается «холодным умом» — минимум на следующий день. Эмоциональные увольнения оспариваются в суде, восстанавливаются в должности, плюс компенсация за вынужденный прогул (часто 5-8 месячных окладов)."},
      {"type":"fact_card","icon":"⚖️","text":"2023 год, IT-компания в Москве, главный бухгалтер уволена «за нарушения» (опоздания на 15-30 минут несколько раз). Бухгалтер подала иск в суд. Дело длилось 8 месяцев. Суд: опоздания зафиксированы только устно (нет актов), письменных объяснений не запрашивали, предупреждений не было, дисциплинарных взысканий до увольнения не объявляли. Процедура нарушена полностью. Восстановлена в должности + компенсация 740 тыс руб (8 окладов за вынужденный прогул). Компания потеряла 740 тыс + репутацию + время + личное время директора на 8 месяцев. Урок: 81-я статья ТК — это «оружие массового поражения юриста противника», без идеальной процедуры использовать нельзя."},
      {"type":"text_block","title":"После сложного разговора — что делать с собой","text":"Сложные разговоры эмоционально дорогие. После увольнения нормально чувствовать вину, тяжесть, сомнения. Это не повод откладывать следующий нужный разговор. Что помогает: 1) Поговорить с коллегой (не с подчинёнными, не с руководством — с равным). 2) Записать в журнал что сделал хорошо, что бы изменил — это снижает повтор ошибок. 3) Дать себе 24 часа на восстановление, не назначать в этот день других сложных разговоров. 4) Помнить — если разговор был необходим, откладывание делало бы хуже всем. Иногда увольнение — это акт милосердия (человек страдает на неподходящей работе)."},
      {"type":"fact_card","icon":"👨‍💼","text":"Александр Костромин, HR-директор крупного холдинга, 25 лет в HR, провёл лично более 800 увольнений. Его слова: «Я ни разу не слышал «спасибо» после увольнения — это нормально. Но три раза, через 2-3 года, бывшие сотрудники писали: «Когда вы меня уволили, я был в ярости. Сейчас понимаю — это было лучшее, что могло со мной случиться. Я нашёл то, в чём действительно силён». Это и есть смысл хорошего HR — иногда дать человеку возможность найти своё. Плохое увольнение — позорное. Хорошее увольнение — респект к человеку, который попал не туда»."}
    ]$blocks$::jsonb,
    25, ARRAY['hr','увольнение','фидбек','коммуникация'], false, 'published', 'manual',
    NOW(), CURRENT_DATE
  )
  RETURNING id
)
INSERT INTO office_academy_quiz_questions (lesson_id, sort_order, question_type, question_text, options, correct_explanation)
SELECT lesson.id, q.so, q.qt, q.qtext, q.opts::jsonb, q.expl FROM lesson, (VALUES
  (1, 'choice', 'Что значит SBI в модели фидбека?',
   '[{"id":1,"text":"Salary, Bonus, Incentive","is_correct":false},{"id":2,"text":"Situation, Behavior, Impact","is_correct":true},{"id":3,"text":"Strict, Brief, Important","is_correct":false},{"id":4,"text":"Start, Build, Improve","is_correct":false}]',
   'SBI = Situation (ситуация — где и когда), Behavior (поведение — что человек сделал), Impact (влияние — что это вызвало). Это структура хорошего корректирующего фидбека.'),
  (2, 'choice', 'Сколько времени по ТК РФ есть на наложение взыскания с момента обнаружения нарушения?',
   '[{"id":1,"text":"1 неделя","is_correct":false},{"id":2,"text":"1 месяц","is_correct":true},{"id":3,"text":"3 месяца","is_correct":false},{"id":4,"text":"Год","is_correct":false}]',
   'По ст. 193 ТК РФ — 1 месяц с момента обнаружения проступка (не считая болезни и отпуска работника). После — нельзя наложить взыскание за это нарушение.'),
  (3, 'truefalse', 'Корректирующий фидбек лучше делать публично — все услышат и не повторят.',
   '[{"id":1,"text":"Верно","is_correct":false},{"id":2,"text":"Неверно — публично хвалить, корректировать один на один","is_correct":true}]',
   'Публичный корректирующий фидбек = унижение. Сотрудник запомнит обиду, а не урок. Правило: «хвали публично, ругай приватно». Один на один в закрытой комнате, без свидетелей.'),
  (4, 'choice', 'Самый цивилизованный путь увольнения:',
   '[{"id":1,"text":"По 81 статье за нарушения","is_correct":false},{"id":2,"text":"По соглашению сторон (ст. 78 ТК)","is_correct":true},{"id":3,"text":"По собственному желанию через давление","is_correct":false},{"id":4,"text":"По несоответствию должности","is_correct":false}]',
   'Соглашение сторон — самый чистый путь: договариваемся об условиях (компенсация, дата), подписываем соглашение, расходимся без обид. Дёшево, быстро, без репутационных рисков. Увольнение по 81 ТК часто оспаривается в суде.'),
  (5, 'scenario', 'Сотрудник опоздал 3 раза за месяц. Что делать сначала?',
   '[{"id":1,"text":"Сразу уволить за нарушения","is_correct":false},{"id":2,"text":"Запросить письменные объяснения, поговорить голосом — может быть причина (болезнь ребёнка, болезнь самого)","is_correct":true},{"id":3,"text":"Игнорировать — мелочь","is_correct":false},{"id":4,"text":"Опубликовать в общем чате","is_correct":false}]',
   'Сначала разобраться с причинами через разговор и письменные объяснения. Может быть личная ситуация (ребёнок в больнице, болезнь родителей). Если объяснение неубедительно — устное предупреждение. Если повторится — выговор. Увольнение возможно только после процедуры с предупреждениями.'),
  (6, 'choice', 'Когда планировать разговор об увольнении?',
   '[{"id":1,"text":"Утро понедельника или вторника","is_correct":true},{"id":2,"text":"Вечер пятницы перед выходными","is_correct":false},{"id":3,"text":"В обеденный перерыв","is_correct":false},{"id":4,"text":"В день рождения сотрудника","is_correct":false}]',
   'Утро понедельника или вторника — у человека есть время и силы обработать, заняться поиском работы. Пятница вечер — особенно жестоко (испорченные выходные, никого нет помочь). День рождения — само собой нельзя.'),
  (7, 'truefalse', 'Можно уволить сотрудника на эмоциях сразу после конфликта.',
   '[{"id":1,"text":"Верно","is_correct":false},{"id":2,"text":"Неверно — минимум сутки на «холодный ум»","is_correct":true}]',
   'Эмоциональные увольнения оспариваются в суде. Восстановление в должности + компенсация за вынужденный прогул (5-8 окладов). Решение об увольнении принимается на следующий день минимум, согласованное с HR и юристом.'),
  (8, 'scenario', 'Сотрудник в разговоре об увольнении заплакал. Что делать?',
   '[{"id":1,"text":"Передумать и оставить","is_correct":false},{"id":2,"text":"Дать время (5-10 минут пауза), не давить, ответить на вопросы по фактам, дать копию соглашения и время подумать до конца дня","is_correct":true},{"id":3,"text":"Закончить разговор и убежать","is_correct":false},{"id":4,"text":"Сразу позвать HR","is_correct":false}]',
   'Эмоции — нормальная реакция, нужно дать время. НЕ передумывать (решение было принято холодным умом, эмоции собеседника его не меняют). НЕ оправдываться («мне тоже тяжело»). НЕ убеждать. Молчание и пауза — нормально. Когда человек успокоится — продолжить по фактам.'),
  (9, 'choice', 'Главная ошибка фидбека:',
   '[{"id":1,"text":"Конкретные примеры","is_correct":false},{"id":2,"text":"Обобщения «ты всегда / никогда»","is_correct":true},{"id":3,"text":"Своевременность","is_correct":false},{"id":4,"text":"Один на один","is_correct":false}]',
   '«Ты всегда опаздываешь» / «Ты никогда не отвечаешь» — обобщения вызывают защиту. Конкретно: «вчера в 10:35 ты пришёл на совещание, которое было назначено на 10:00». Конкретику не оспоришь, обобщение всегда «нет, не всегда».'),
  (10, 'truefalse', 'Лучшая практика — копить негативный фидбек на годовой review.',
   '[{"id":1,"text":"Верно","is_correct":false},{"id":2,"text":"Неверно — регулярно маленькими порциями","is_correct":true}]',
   'Накопление негатива на годовой review = удар, который человек не может ничего изменить (всё в прошлом). Регулярный фидбек раз в 2-4 недели маленькими порциями работает в 10 раз лучше — можно исправить, увидеть прогресс, договориться о новых правилах.')
) AS q(so, qt, qtext, opts, expl);

